import "support.gst" as protected;
type Choice enum { Picked { token: int } }
func log_ref(value: &int) { unsafe { os.LogInt(*value); } }
func main() int {
 mut ctx := os.Arena.New(); defer ctx.Free();
 mut value := 11; mut token := &value; defer log_ref(token);
 mut choice: Choice;
 unsafe { choice.tag = 0; choice.Picked.token = 22; }
 match choice { Picked { token } => {
  defer log_ref(token);
  if 1 == 1 { mut value := 99; mut token := &value; return 0; }
 } }
 return 0;
}
